		lowering.setProjectionContext(Var.of("callerGraph"));
		lowering.setInheritedGraphParameter("privateGraph");
		MapBindingSet caller = new MapBindingSet();
		caller.addBinding("callerGraph", graph);
		BindingSet supplied = ProjectionQueryEvaluationStep.withInheritedGraphInput(lowering, caller, context);
		assertTrue(GraphFrameBindings.isSupplied(supplied, "privateGraph"),
				"real SELECT input lowering supplies the source graph");
		QueryBindingSet hidden = new QueryBindingSet();
		hidden.addBinding("payload", vf.createLiteral("row"));
		BindingSet narrowed = GraphFrameBindings.preserve(supplied, hidden);
		assertSame(GraphFrameBindings.from(supplied), GraphFrameBindings.from(narrowed));
		assertFalse(narrowed.hasBinding("privateGraph"));
		assertFalse(GraphFrameBindings.isSupplied(narrowed, "privateGraph"));
		QueryBindingSet mappedParent = new QueryBindingSet();
		mappedParent.addBinding("privateGraph", graph);
		BindingSet parent = trustedParent ? GraphFrameBindings.preserve(supplied, mappedParent) : mappedParent;
		assertEquals(trustedParent, GraphFrameBindings.isSupplied(parent, "privateGraph"));
		Projection projection = new Projection(new SingletonSet(),
				new ProjectionElemList(new ProjectionElem("payload")));
		// An actual enclosing projection causes this public projection to retain its parent mapping.
		new Projection(projection, new ProjectionElemList());
		QueryEvaluationStep source = ignored -> new SingletonIteration<>(narrowed);
		List<BindingSet> expected;
		try (var rows = new ProjectionIterator(projection, source.evaluate(parent), parent, context,
				ProjectionIterator.parameterSources(projection.getArg(),
						List.of(projection.getProjectionElemList())))) {
			expected = QueryResults.asList(rows);
		}
		assertEquals(1, expected.size());
		assertEquals(graph, expected.getFirst().getValue("privateGraph"));
		assertEquals(trustedParent, GraphFrameBindings.isSupplied(expected.getFirst(), "privateGraph"),
				"a hidden source descriptor cannot qualify an equal-valued untrusted parent binding");
